  'settings.reconnect.upnpLocationHint': 'Voliteľné a zvyčajne prázdne. Vyplňte len tam, kde je multicastové hľadanie odfiltrované, no samotná brána je bez problémov dostupná, čo samotné objavovanie nikdy nespraví.',

