  'settings.reconnect.checkTitle': 'Kontrola adresy',
  'settings.reconnect.checkUrl': 'URL na kontrolu IP',
  'settings.reconnect.checkUrlHint': 'Stiahne sa pred behom metódy a ešte raz po ňom; beh je hotový, len čo sa adresa, ktorú vypíše, zmení. Predvolená hodnota tu zámerne nie je: správca sťahovania, ktorého si hostujete sami, by nemal začať hlásiť vašu adresu službe, ktorú ste si nikdy nevybrali. To, čo vypíše, musí byť adresa, ktorú vidí internet, lebo stránka vracajúca adresu z vašej vlastnej siete nerozozná opätovné pripojenie od ničoho.',
  'settings.reconnect.checkPresets': 'Známe služby',
