  'settings.chunks': 'Spojenia na jedno sťahovanie (0 = automaticky)',
  'settings.chunksHint': 'Koľkými spojeniami beží jedno sťahovanie, keď neplatí nič konkrétnejšie. Pravidlo alebo jedno konkrétne sťahovanie môže uviesť vlastné číslo a prebíja toto. Hoster, ktorý znesie menej, dostane aj tak menej: limit hostera môže číslo len znížiť, nikdy zvýšiť. Pri 0 rozhoduje aplikácia. Viac než hŕstka spojení u hostera s limitom na súbor neprinesie nič a je spoľahlivou cestou, ako si nechať označiť účet.',
  'task.chunks': 'Spojenia (0 = globálne nastavenie)',
  'task.chunksHint': 'Koľkými spojeniami beží toto jedno sťahovanie. Prebíja globálne nastavenie aj každé pravidlo, ktoré ho nastavilo, ale nikdy hostera: hoster, ktorý znesie menej, dostane aj tak menej. Pri 0 výnimka zaniká a číslo sa opäť rozhoduje inde.',
  'columns.connection': 'Spojenie',

  'props.title': 'Vlastnosti',
  'props.mixed': 'Niekoľko hodnôt',
  'props.mixedHint': 'Tieto riadky sa nezhodujú, preto je políčko prázdne. Keď sa ho nedotknete, nič nezmení; napíšte doň a každý vybraný riadok dostane to, čo ste napísali.',
  'props.name': 'Názov',
  'props.nameHint': 'Jeden názov súboru, nikdy cesta: všetko, čo vypisuje priečinky, sa skráti na jediný názov. Dokončené sťahovanie sa premenuje aj na disku, aby si zoznam a priečinok nemohli odporovať. Bežiace si drží súbor, ktorý má jeho backend otvorený, a nový názov prevezme, až keď skončí. Ešte nezačaté ho prevezme hneď. Názov patrí jednému súboru, takže sa toto políčko ponúka len pri jednom riadku.',
  'props.comment': 'Poznámka',
  'props.commentHint': 'Tvoja vlastná poznámka k tomuto odkazu. Uloží sa a zobrazí v zozname; aplikácia sa podľa nej neriadi.',
  'props.priority': 'Priorita',
  'props.priorityHint': 'Vyššia beží skôr. Preskladá to, čo ešte čaká; už bežiace sťahovanie sa späť do frontu neposiela.',
  'props.autoExtract': 'Rozbaliť archívy',
  'props.autoExtractHint': 'Či sa archív rozbalí po dokončení sťahovania. „Dediť“ necháva rozhodnutie na stránke nastavení archívov, čo nie je to isté ako vypnuté. Prepínač sa číta až pri rozbaľovaní, takže ak ho zapneš teraz, rozbalí sa aj niečo, čo skončilo skôr.',
