    'Skript spustí tvoj vlastný JavaScript, keď sa niečo stane - sťahovanie sa dokončí, jedno zlyhá, front sa stane nečinným - alebo na vyžiadanie, z Testovacieho spustenia tu a z položky „Spustiť skript“, ktorú táto vlna pridáva do kontextovej ponuky zoznamu sťahovaní. Pridaj nejaký a začni.',
  'settings.scripts.loadFailed':
    'Skripty sa nepodarilo načítať. Ak tento build ešte neobsahuje automatizačný engine, táto stránka zatiaľ nemá čo zobraziť - skús to znova, keď ho bude obsahovať.',
