  'settings.access.relay.title': 'Relé projektu',
  'settings.access.relay.body': 'Relay je sprostredkovateľ, vďaka ktorému sú všetky tvoje inštancie dostupné aj mimo domácej siete, teda odkiaľkoľvek. Tento poskytuje projekt zadarmo.',
  'settings.access.relay.use': 'Používať relé projektu',
  'settings.access.relay.leadProject': 'Funguje bez nastavovania. Všetko, čo si tvoje inštancie povedia, je zašifrované, a kľúč máš len ty.',
  'settings.access.relay.address': 'Adresa',
  'settings.access.relay.seesButton': 'Čo vidí?',
  'settings.access.relay.seesTip': 'Pre relay neviditeľné: tvoje odkazy, sťahovania, súbory a prístupový token.\n\nPre relay viditeľné: IP adresy tvojich inštancií a kedy niečo pošlú.\n\nTo sa zašifrovať nedá. Ak ti to prekáža, prevádzkuj vlastný relay.',
  'settings.access.relay.none': 'Bez relé',
  'settings.access.relay.noneHint': 'Žiadny relay nie je aktívny. V tej istej sieti, teda doma, sa inštancie stále nájdu samy. Medzi rôznymi sieťami sa nespoja, vzdialený prístup teda nie je možný.',
  'settings.access.relay.own': 'Vlastné relé',
  'settings.access.relay.project': 'Relé projektu',
  'settings.access.relay.whichHint': 'Ide cez {address}',
  'settings.access.relay.savedProject': 'Relé projektu je aktívne',
  'settings.access.relay.savedOwn': 'Tvoje relé je aktívne',
  'settings.access.relay.savedOff': 'Relé vypnuté',
  'settings.access.ownRelay.title': 'Vlastné relé',
  'settings.access.ownRelay.body': 'Prevádzkuj vlastný relay namiesto projektového.',
  'settings.access.ownRelay.use': 'Používať vlastné relé',
  'settings.access.ownRelay.lead': 'Dve cesty: túto inštanciu spravíš relé, alebo zadáš adresu.',
  'settings.access.ownRelay.serveLabel': 'Použiť túto inštanciu ako relay',
  'settings.access.ownRelay.serveHint': 'Funguje len vtedy, ak je táto inštancia dostupná zvonku, napríklad cez Nginx Proxy Manager a vlastnú doménu.',
  'settings.access.ownRelay.serveClients': 'Práve pripojených: {count}.',
  'settings.access.ownRelay.addressLabel': 'Adresa',
  'settings.access.ownRelay.addressPlaceholder': 'napr. https://relay.mojadomena.sk',
  'settings.access.ownRelay.save': 'Uložiť',
  'settings.access.ownRelay.everyInstance': 'Táto adresa platí len pre túto inštanciu. Zadaj ju na každej.',
  'settings.access.ownRelay.containerLabel': 'Ako vlastný kontajner',
  'settings.access.ownRelay.containerHint': 'Ak nie je žiadna z tvojich inštancií dostupná zvonku, relay musí stáť inde: na tvojom serveri alebo malom VPS. Nainštaluj kontajner z Unraid Community Applications alebo príkazom nižšie.\n\nKontajner nepotrebuje nastavenie: spusti, zadaj jeho adresu hore, hotovo. Nič neukladá, takže niet čo zálohovať.',
  'settings.access.tokens.title': 'Tokeny API',
