  'settings.access.identity.title': 'Identita tejto inštancie',
  'settings.access.identity.nameLabel': 'Názov',
  'settings.access.identity.namePlaceholder': 'napr. Domáci server',
  'settings.access.identity.nameHint': 'Ponúkne sa ako prvé pri párovaní a v QR kóde nižšie, namiesto toho, ako tento počítač náhodou pomenoval operačný systém alebo kontajnerové runtime prostredie. Voliteľné - nechajte prázdne, ak chcete naďalej používať ten názov.',
  'settings.access.identity.domainsLabel': 'Známe domény',
  'settings.access.identity.domainsHint': 'Zapamätá sa automaticky, hneď ako cez ňu skutočne prvýkrát dorazí požiadavka, takže tu zostane uvedená, aj keď neskoršie požiadavky prichádzajú namiesto toho cez LAN IP. Pridajte jednu ručne pre doménu, ktorá je už nastavená, ale zatiaľ cez ňu nikto nenavštívil - jedna celá adresa na riadok, napr. https://kl.example.com.',
  'settings.access.cardTitle': 'Prepojenie inštancií a vzdialený prístup',
  'settings.access.phrase.body': 'Jedna fráza prepojí všetky vaše KnightLoadery. Vytvorte ju tu a vložte do ostatných inštancií - bez účtu, bez prihlásenia, nič sa nenastavuje.',
  'settings.access.phrase.noPasswordWarning': 'Táto inštancia nemá heslo. Fráza otvorí každú inštanciu, ktorú ňou prepojíte, takže kto si ju tu prečíta, dostane sa ku všetkým, nielen k tejto. Radšej najprv nastavte heslo vyššie.',
  'settings.access.phrase.activate': 'Vytvoriť frázu',
  'settings.access.phrase.howLead': 'Dvanásť slov a nič viac. Takto na to a toto sa pritom deje:',
  'settings.access.phrase.howStep1': 'Na tejto inštancii stlač „{button}“. Objaví sa dvanásť slov.',
  'settings.access.phrase.howStep2': 'Otvor KnightLoader na druhom stroji, choď na túto stránku, stlač „{button}“ a napíš dvanásť slov.',
  'settings.access.phrase.howStep3': 'Hotovo! Každá inštancia sa teraz objaví u tej druhej pod „Inštancie“ a môžeš ovládať ktorúkoľvek z ktorejkoľvek. So zapnutým relayom sú tvoje inštancie dostupné aj zvonku tvojej siete.',
  'settings.access.phrase.howWhat': 'Slová sú tajomstvo, nie adresa. Každá inštancia z nich vypočíta dva kľúče: jeden na nájdenie ostatných, druhý na šifrovanie.\n\nAby sa našli, volá každá inštancia sama na to isté miesto stretnutia na internete. Kto ukáže rovnaký kľúč, ten je spojený. Preto nemusí byť žiadna z tvojich inštancií dostupná zvonku.\n\nMiesto stretnutia nemôže čítať. Tvoje slová nikdy nevidí a všetko, čo cezeň prejde, je zašifrované druhým kľúčom.',
  'settings.access.phrase.statusDisconnected': 'Nepripojené',
  'settings.access.phrase.statusHintProject': 'Pripojené k relayu projektu. Vzdialený prístup je nastavený.',
  'settings.access.phrase.statusHintOwn': 'Pripojené k vlastnému relayu. Vzdialený prístup je nastavený.',
  'settings.access.phrase.statusHintOff': 'Žiadny relay nie je aktívny. Tvoje inštancie sú dostupné len v miestnej sieti.',
  'settings.access.phrase.statusHintLost': 'Bez spojenia s relayom. KnightLoader to skúša ďalej. Dovtedy sa inštancie nájdu len v miestnej sieti.',
  'settings.access.phrase.statusConnected': 'Pripojené',
  'settings.access.phrase.howButton': 'Ako to funguje?',
  'settings.access.phrase.joinButton': 'Zadať frázu',
  'settings.access.phrase.joinPlaceholder': 'Vložte dvanásť slov z druhej inštancie',
  'settings.access.phrase.joinConfirm': 'Prepojiť',
  'settings.access.phrase.errChecksum': 'Táto fráza neplatí - skontroluj, či nie je niektoré slovo preklepnuté alebo prehodené.',
  'settings.access.phrase.errUnknownWord': 'Slovo {position} („{word}“) nepatrí medzi povolené slová.',
  'settings.access.phrase.errWordCount': 'Je to {count} slov - fráza ich potrebuje {need}.',
  'settings.access.phrase.yourPhrase': 'Vaša prepojovacia fráza',
  'settings.access.phrase.pasteHint': 'Vložte týchto dvanásť slov do každej ďalšej inštancie, ktorú chcete prepojiť.',
  'settings.access.phrase.qrHint': 'Alebo to načítaj druhým zariadením namiesto prepisovania.',
  'settings.access.phrase.revealWhy': 'Na opätovné zobrazenie zadajte heslo tejto inštancie. Fráza otvorí každú inštanciu v skupine, nielen túto.',
