  'settings.nav.browsertools': 'Prehliadač a aplikácia',
  'settings.browsertools.bookmarkletStep1': 'Presuň tlačidlo nižšie na panel záložiek prehliadača - uloží sa ako každá iná záložka, nič sa neinštaluje.',
  'settings.browsertools.bookmarkletStep2': 'Na ktorejkoľvek stránke naň klikni (najprv vyber text, ak chceš len ten). Otvorí sa malá karta KnightLoader s odkazom na túto stránku alebo vybraným textom, už vyplnená - skontroluj ju a pridaj odtiaľ ako stiahnutie.',
