  'settings.nav.resolvers': 'Resolvery',
  'settings.module.ytdlp': 'yt-dlp',
  'settings.resolvers.moduleUnavailable': 'Modul nie je dostupný',
  'settings.resolvers.moduleUnavailableHint': 'Všetko nižšie sa aj tak ukladá a prejaví sa hneď, ako bude yt-dlp k dispozícii - úpravou už teraz sa nič nestratí.',
  'settings.resolvers.intro': 'Konfigurácia backendu yt-dlp, ktorý sťahuje mediálne a streamovacie stránky podporované samotným yt-dlp. Ktorá služba vôbec spracuje daný odkaz - yt-dlp, debrid účet, headless sidecar JD - sa rozhoduje podľa poradia smerovania na stránke Účty; tu ide len o to, čo robí yt-dlp, keď je naň odkaz už nasmerovaný.',
  'settings.resolvers.quality': 'Kvalita',
  'settings.resolvers.qualityHint': 'Ktorý selektor -f sa použije pri spustení yt-dlp. Najlepšia dostupná je vlastná predvolená hodnota yt-dlp a to, čo používalo každé sťahovanie pred vznikom tohto nastavenia.',
  'settings.resolvers.quality.best': 'Najlepšia dostupná',
  'settings.resolvers.quality.2160p': 'Až do 2160p (4K)',
