  'settings.resolvers.customFormatHint': 'Vlastná hodnota -f pre yt-dlp, napr. bestvideo[height<=720]+bestaudio/best. Odovzdáva sa bez kontroly; hodnota, ktorú yt-dlp odmietne, zlyhá s jeho vlastnou chybou v úlohe.',
  'settings.resolvers.playlist': 'Stiahnuť celý playlist, keď odkaz vedie do neho',
