  'settings.resolvers.subtitleLangsHint': 'Vlastná hodnota --sub-langs pre yt-dlp, napr. en,de. Prázdne znamená predvolené en.',
  'settings.resolvers.subtitleAuto': 'Sťahovať aj automaticky generované titulky, keď neexistuje ručná stopa',
  'settings.resolvers.outputTitle': 'Názov výstupného súboru',
  'settings.resolvers.outputHint': 'Vlastná šablóna -o pre yt-dlp. Prázdne použije vstavanú %(title)s.%(ext)s. Môže obsahovať podpriečinky, napr. %(uploader)s/%(title)s.%(ext)s.',

  'settings.nav.torrents': 'Torrenty',
  'settings.module.torrents': 'Torrenty',
  'settings.torrents.title': 'Torrenty',
  'settings.torrents.subtitle': 'Ciele seedovania, limity prenosu, mapovanie portu a DHT/PEX pre magnet odkazy a súbory .torrent.',
  'settings.torrents.seedingTitle': 'Seedovanie',
  'settings.torrents.seedRatio': 'Cieľový pomer seedovania',
  'settings.torrents.seedRatioHint': 'Pokračuje v seedovaní dokončeného torrentu, kým sa do roja nevráti tento pomer vzhľadom na jeho vlastnú veľkosť. 0 = žiadny cieľ pomeru.',
  'settings.torrents.seedDuration': 'Cieľový čas seedovania',
  'settings.torrents.seedDurationHint': 'Pokračuje v seedovaní dokončeného torrentu po tento čas od dokončenia. 0 = žiadny časový limit. Seedovanie sa zastaví, keď sa dosiahne prvý z oboch cieľov vyššie.',
  'settings.torrents.seedDurationUnit': 'hodín',
  'settings.torrents.transferTitle': 'Limit prenosu',
  'settings.torrents.uploadLimit': 'Limit odosielania',
  'settings.torrents.uploadLimitHint': 'Obmedzuje, ako rýchlo torrent odosiela dáta do roja počas seedovania. 0 = bez obmedzenia.',
  'settings.torrents.uploadLimitUnit': 'KiB/s',
  'settings.torrents.portTitle': 'Port a mapovanie',
  'settings.torrents.port': 'Port',
  'settings.torrents.portHint': 'Port, na ktorom táto inštancia počúva pripojenia roja. 0 necháva výber na torrentovom engine.',
  'settings.torrents.portMapHint': 'Požiada router o presmerovanie vyššie uvedeného portu na tento počítač cez UPnP, aby ho peeri za iným routerom aj tak dosiahli. Nie každý router to podporuje a niektoré žiadosť prijmú, aj keď to v skutočnosti nefunguje.',
  'settings.torrents.portMapButton': 'Skúsiť mapovanie UPnP',
  'settings.torrents.portMapping': 'Pýtam sa routera…',
  'settings.torrents.portMapNeedsPort': 'Najprv nastav port vyššie, kým ho namapuješ - pri 0 router nemá kam presmerovať.',
  'settings.torrents.portMapConfirmed': 'Potvrdené: port {port} je namapovaný a bola overená jeho dostupnosť.',
  'settings.torrents.portMapUnconfirmed': 'Router žiadosť prijal, ale nepodarilo sa potvrdiť, že mapovanie skutočne funguje. Niektoré routery to robia potichu - skús overiť dostupnosť zvonku siete.',
  'settings.torrents.portMapFailed': 'Port sa nepodarilo namapovať: {error}',
  'settings.torrents.portMapUnavailable': 'Táto verzia zatiaľ mapovanie portu neponúka.',
  'settings.torrents.networkTitle': 'Vyhľadávanie peerov',
  'settings.torrents.dht': 'DHT',
  'settings.torrents.dhtHint': 'Nájde peerov bez trackeru, pomocou iných klientov BitTorrent ako distribuovaného zoznamu.',
  'settings.torrents.pex': 'Výmena peerov (PEX)',
  'settings.torrents.pexHint': 'Vymieňa známych peerov s už pripojenými, aby sa roj s málo peermi našiel rýchlejšie.',
  'settings.torrents.privateNote': 'Súkromný torrent automaticky vypne obe funkcie, hneď ako sú známe jeho metadáta, bez ohľadu na nastavenie tu - pri nahranom súbore .torrent okamžite, pri magnet odkaze hneď, ako jeho vlastné metadáta dorazia z roja. Väčšina súkromných trackerov banuje účty, ktoré čokoľvek z toho používajú.',
  'settings.torrents.engineNote': 'Cieľový pomer seedovania, cieľový čas seedovania a port teraz ovplyvňujú každý torrent, ktorý tento engine spustí - port však len pre úplne prvý torrent od posledného reštartu tejto inštancie, pretože vlastný torrentový klient enginu sa zostaví len raz a potom už nikdy znova; neskoršie uloženie sa napriek tomu uloží správne a začne platiť od nasledujúceho reštartu. Limit odosielania sa zatiaľ len ukladá a overuje, engine ho zatiaľ nemá ako premietnuť do prebiehajúceho sťahovania. DHT a PEX nižšie sú na tom rovnako pri bežnom (nie súkromnom) torrente: vlastná predvolená hodnota tejto inštancie tiež zatiaľ nedosahuje prebiehajúce sťahovanie, takže torrent sa naďalej seeduje s oboma zapnutými bez ohľadu na nastavenie tu - súkromný torrent je úplne iný prípad, pozri poznámku nižšie. Tlačidlo mapovania nižšie napriek tomu robí niečo skutočné: úprimne požiada router o presmerovanie čísla portu zadaného vyššie, či už naň torrent práve počúva, alebo nie.',
  'torrent.staging': 'Pridáva sa…',
