  'onboarding.step': 'Krok {n} z {total}',
  'onboarding.skip': 'Preskočiť',
  'onboarding.back': 'Späť',
  'onboarding.next': 'Ďalej',
  'onboarding.finish': 'Začať používať KnightLoader',
  'onboarding.welcome.title': 'Vitaj v KnightLoaderi',
  'onboarding.welcome.body': 'KnightLoader je samostatne prevádzkovaný správca sťahovania: vlož alebo pretiahni odkaz a vyzdvihne ho ten backend, ktorý ho skutočne spracúva - vstavaný engine pre bežné odkazy na súbory, yt-dlp pre mediálne stránky, debrid službu pre hosterov, za ktorých už platíš, alebo bezhlavý JDownloader pre všetko ostatné. Táto krátka prehliadka pokrýva jediné nastavenie, ktoré sa oplatí skontrolovať pred začiatkom.',
  'onboarding.welcome.langLabel': 'Jazyk rozhrania',
  'onboarding.folder.title': 'Kam majú smerovať súbory?',
  'onboarding.folder.body': 'Toto je priečinok, do ktorého sa zapisujú dokončené sťahovania. Napíš cestu alebo si ju vyhľadaj prehliadaním servera - kedykoľvek ju môžeš znova zmeniť na stránke všeobecných nastavení.',
  'onboarding.accounts.title': 'Prémioví hosteri, kedykoľvek ich budeš chcieť',
  'onboarding.accounts.body': 'Front funguje úplne bez účtu. Keď budeš chcieť plnú rýchlosť u hostera alebo debrid služby, ktorú už platíš, pridaj jej prihlásenie v Účtoch - teraz tu nič netreba nastavovať.',
  'onboarding.accounts.link': 'Otvoriť Účty',
  'onboarding.finished.title': 'Máš hotovo',
