  'settings.nav.shortcuts': 'Skratky',
  'settings.shortcuts.subtitle': 'Všetky príkazy s predvolenou klávesovou skratkou, zoskupené podľa toho, kde platia. Zmeň priradenie, alebo ho obnov na predvolené.',
  'settings.shortcuts.empty': 'Zatiaľ žiadny príkaz nemá predvolenú skratku.',
  'settings.shortcuts.change': 'Zmeniť',
  'settings.shortcuts.reset': 'Obnoviť',
  'settings.shortcuts.resetAll': 'Obnoviť všetko na predvolené',
  'settings.shortcuts.resetAllConfirmTitle': 'Obnoviť všetky skratky?',
  'settings.shortcuts.resetAllConfirmBody': 'Každá znova priradená skratka sa vráti na predvolenú hodnotu. Toto nemožno vrátiť späť.',
