  'settings.downloads.diskTitle': 'Miesto na disku',
  'settings.downloads.diskHint': 'Tri čísla, ktoré zadržia sťahovania skôr, než sa disk naplní, a nie potom. Všetky tri znamenajú voľné bajty na tom disku, na ktorý sa práve zapisuje, takže pracovný priečinok na inom disku sa meria na ňom. Nula príslušné číslo vypne. Všimni si, čo to nedokáže: nie každý systém sa dá spýtať, koľko miesta je voľné, a tam, kde odpoveď nie je, sa nikdy nič nezadrží, lebo stráž, ktorá blokuje, keď nevie, by zastavila úplne zdravý stroj.',
