  'settings.headerProfiles.title': 'Profily hlavičiek',
  'settings.headerProfiles.hint': 'Niektoré stránky vydajú súbor len prihlásenému prehliadaču, alebo len vtedy, keď požiadavka prichádza z niektorej ich vlastnej stránky. Profil uloží hlavičky pre práve jednu stránku, zašifrované rovnako ako tvoje prihlasovacie údaje, a KnightLoader ich posiela s každým sťahovaním z tejto stránky.',
  'settings.headerProfiles.empty': 'Zatiaľ žiadne profily hlavičiek.',
  'settings.headerProfiles.emptyHint': 'Jeden sa oplatí hneď, ako nejaké sťahovanie vyjde len vtedy, keď si v prehliadači prihlásený.',
