  'settings.rules.action.category': 'Kategória',
  'settings.rules.action.categoryHint': 'Zakladá zhodné odkazy do jednej zo zásuviek zo stránky Kategórie, ktorá si so sebou nesie vlastný priečinok, miesto vo fronte, prepínač rozbaľovania a pravidlo pre súbor, ktorý už tam je. Ponechané na „Bez zmeny“ a žiadne pravidlo k tomu nehovorí nič, takže odkaz zostane nezaradený. Ak toto pravidlo uvádza aj priečinok na sťahovanie, vyhráva ten priečinok a zásuvka dodá všetko ostatné. Uviesť zásuvku, ktorá bola odstránená, sa pri uložení odmietne, lebo pravidlo ukazujúce na zásuvku, ktorá tam nie je, neurobí pri každom zhodnom odkaze vôbec nič, a to bez jediného slova.',
  'settings.rules.action.categoryNone': 'Zatiaľ žiadne kategórie. Najprv nejakú založ na stránke Kategórie, inak by toto pravidlo zakladalo odkazy do zásuvky, ktorá neexistuje.',
