  'detail.onDiskHint': 'Koľko súbor v tejto sekunde meria na disku, zistené na serveri a nie počítané tu. Bežiace sťahovanie medzi dvoma pohľadmi narastie, a nie je to veľkosť, ktorú ohlásil hoster.',
  'detail.mirrorOf': 'Náhradná kópia pre',
  'detail.times': 'Časové značky',
  'detail.timesHint': 'Kedy tento odkaz prišiel, kedy sa naposledy zmenil a kedy sa usadil. Čas, kedy sa prenos začal, tu nie je: aplikácia si ho nikdy nikam nepoznačila, a hodnota odhadnutá z tých troch by bola číslo, podľa ktorého sa ľudia zariadia.',
  'detail.nextTry': 'Ďalší pokus',
  'detail.stalledSince': 'Stojí od',
  'detail.retries': 'Doterajšie opakovania',
  'detail.retriesHint': 'Koľkokrát sa toto sťahovanie po zlyhaní skúsilo znova. Vo chvíli, keď sa sťahovanie dokončí, sa vynuluje, takže hotový riadok ukazuje nulu, aj keď to trvalo štyri pokusy. Koľko pokusov ešte zostáva, tu nestojí: strop závisí od príčiny a od hostera, a táto stránka ho nedokáže vypočítať.',
  'detail.stallRestarts': 'Reštarty po zastavení',
  'detail.stallRestartsHint': 'Koľkokrát stráž stojacich sťahovaní spustila toto sťahovanie sama od seba znova. Keď sa sťahovanie dokončí, vynuluje sa, rovnako ako počítadlo vyššie.',
  'detail.failure': 'Čo sa pokazilo',
  'detail.cause': 'Príčina',
  'detail.message': 'Čo povedal backend',
  'detail.messageHint': 'Veta od toho, čo sa o toto sťahovanie pokúsilo, slovo za slovom a nepreložená. Je to aktuálne zlyhanie a nič iné: reštart ju zmaže a staršie sa nikde neuchovávajú.',
  'detail.heldBack': 'Zadržiava ho',
  'detail.doing': 'Práve robí',
  'detail.filtered': 'Zadržané filtrom odkazov',
  'detail.gaveUp': 'Žiadny ďalší pokus',
  'detail.gaveUpHint': 'Tu je koniec zámerný, nie preto, že by sa minuli pokusy: captcha, plný disk alebo pravidlo, ktoré pre tohto hostera hovorí „nikdy“. Zvýšiť počet pokusov na tom nič nezmení. Samotné označenie sa nezapisuje do databázy, po reštarte je teda preč, hoci dôvod preň zostáva.',
  'detail.rules': 'Pravidlá, ktoré toto sformovali',
  'detail.rulesHint': 'Pravidlá, ktoré na tento odkaz zabrali pri jeho príprave, v poradí, v akom bežali. Sú uložené podľa názvu: pravidlo, ktoré bolo odvtedy premenované, sa už nenájde, a pravidlo, ktoré názov nikdy nemalo, je uložené s pozíciou, ktorú vtedy malo. Kliknutím sa otvorí v editore pravidiel.',
  'detail.openRule': 'Otvoriť v editore pravidiel',
  'detail.noRules': 'Tohto odkazu sa nedotklo žiadne pravidlo.',
  'detail.player': 'Prehrať',
  'detail.play': 'Prehrať tu',
  'detail.playHint': 'Prehrá súbor priamo z tejto inštancie, bez toho, aby sa sťahoval druhý raz. Kým nestlačíš prehrávanie, nič sa neťahá, a súbor zostáva tam, kde je.',
  'detail.playPartial': 'Toto sťahovanie nie je dokončené. Prehrať sa dá len tá časť, ktorá už je na disku, preskočiť za ňu nejde, a niektoré súbory neprehrajú vôbec nič, kým tam nie je posledný bajt.',
