  'settings.rules.notFound': 'Žiadne pravidlo sa tu nevolá „{name}“. Bolo premenované alebo odstránené odvtedy, čo pribudol odkaz, ktorý ho uvádza.',

  'notifications.title': 'Oznámenia',
  'notifications.titleHint': 'Pri každej udalosti sa rozhodni, či sa ukáže ako bublina v aplikácii, ako oznámenie tvojho operačného systému, alebo vôbec. Systémové oznámenie sa k tebe dostane, len kým je otvorená karta KnightLoadera, a tichý režim nižšie platí navyše.',
