  'notifications.event.downloadDoneHint': 'Každé sťahovanie, ktoré dobehne do konca, sa ozve. Dvesto súborov vo fronte znamená dvesto takýchto oznámení, takže si dobre rozmysli, či ich pošleš do systému.',
  'notifications.event.downloadFailed': 'Sťahovanie zlyhalo',
  'notifications.event.downloadFailedHint': 'Sťahovanie, ktoré to vzdalo. Tichý režim toto nikdy neskryje.',
  'notifications.event.extractionDone': 'Rozbaľovanie dokončené',
  'notifications.event.extractionDoneHint': 'Archív, ktorý sa dorozbaľoval. Doteraz to nikde nič nehlásilo, preto je na začiatku nastavené na „Nezobrazovať nič“.',
  'notifications.event.extractionFailed': 'Rozbaľovanie zlyhalo',
  'notifications.event.extractionFailedHint': 'Archív, ktorý skončil bez dokončenia. Zvyčajne chýba heslo, a súbory zostanú ležať, kým sa tomu nebudeš venovať.',
  'notifications.event.captchaWaiting': 'Čaká captcha',
  'notifications.event.captchaWaitingHint': 'Okno s captchou sa v tejto karte otvorí tak či tak. Na začiatku je na „Nezobrazovať nič“, lebo kým sa naň dívaš, je to okno samo tým oznámením. Prepni to na systémové oznámenie a captcha ťa zastihne aj v karte na pozadí, skôr než hoster zahodí reláciu.',
  'notifications.event.captchaFailed': 'Captcha zlyhala',
  'notifications.event.captchaFailedHint': 'Nikto neodpovedal včas, alebo odpoveď neprešla. Sťahovanie za ňou zostáva ležať.',
  'notifications.event.captchaResolved': 'Captcha zodpovedaná inde',
  'notifications.event.captchaResolvedHint': 'Zodpovedal ju niekto v inom prehliadači alebo automatický riešiteľ, a okno sa samo zavrelo.',
  'notifications.systemUnavailable': 'Systémové oznámenia tu nie sú k dispozícii: prehliadač ich ponúka len cez HTTPS alebo na localhoste. Všetko na tejto karte sa aj tak zobrazuje v aplikácii.',
  'notifications.systemBlocked': 'Prehliadač pre túto adresu oznámenia blokuje. Riadky nastavené na „Systémové oznámenie“ sa namiesto toho zobrazujú v aplikácii, kým ich v nastaveniach stránky vo svojom prehliadači znova nepovolíš.',
  'notifications.systemNotGranted': 'Prehliadač povolenie neudelil, táto udalosť teda zostáva v aplikácii. Vyber „Systémové oznámenie“ znova, aby sa opýtal ešte raz.',
