  'views.clearAll': 'Vymazať hľadanie a všetky filtre',
  'views.clearAllHint': 'Hľadanie a filtre zostávajú nastavené, aj keď túto stránku opustíš a vrátiš sa. Uvidíš teda znova ten zoznam, ktorý si opustil. Týmto si vrátiš celý zoznam. Uložených zobrazení sa to nedotkne.',

  'disk.title': 'Cieľové priečinky',
  'disk.hint': 'Voľné a obsadené miesto v každom priečinku, do ktorého môže sťahovanie pristáť, a k tomu množstvo, ktoré tam front ešte musí zapísať. Hodnoty pochádzajú z tej istej otázky, proti ktorej sa kontrolujú aj hranice disku, a sú nanajvýš pár sekúnd staré. Voľné a obsadené nedajú vždy dokopy veľkosť disku: súborový systém si kus drží pre systém a kvóta na používateľa môže tejto inštancii nechať menej, než disk naozaj má. Dva priečinky na tom istom disku ukazujú každý ten istý disk, nikdy teda riadky nespočítavaj.',
  'disk.free': 'Voľné',
  'disk.used': 'Obsadené',
  'disk.size': 'Veľkosť disku',
  'disk.queued': 'Ešte sa zapíše',
  'disk.queuedHint': 'Čo by do tohto priečinka pridali sťahovania, ktoré sú ešte dlžné: veľkosť, ktorú ohlásil hoster, mínus to, čo už prišlo. Sťahovanie, ktorého veľkosť hoster neprezradí, sa tu ráta ako nula, je to teda dolná hranica a nikdy nie sľub, a preto môže vedľa celého radu sťahovaní stáť nula bajtov. Vypnuté sťahovania sa nerátajú, rovnaké pravidlo ako pri počítadlách pod zoznamom. Sťahovanie, ktoré už beží, má miesto na disku obvykle vyhradené hneď od štartu, jeho bajty teda vo voľnom mieste vedľa už chýbajú a nepripočítavajú sa navrch.',
  'disk.tasks': 'Sťahovaní: {n}',
  'disk.unknown': 'Tento systém nehlási voľné miesto',
  'disk.unknownHint': 'Nie každého jadra sa dá spýtať, koľko miesta na disku ešte zostáva, a tento build nemá pre to, na ktorom beží, žiadny vhodný spôsob. Tam, kde odpoveď chýba, sa nikdy nič nezadrží: sťahovania sa spúšťajú presne tak ako predtým, než hranice disku vôbec vznikli. Tento riadok tu stojí preto, aby si to vedel odlíšiť od disku, ktorý je naozaj plný.',
  'disk.missing': 'Zatiaľ nevytvorený',
  'disk.missingHint': 'Tento priečinok vytvorí ten, kto doň zapíše prvý súbor, zatiaľ teda neexistuje. Hodnoty popisujú {path}, najbližší existujúci priečinok nad ním, a ten leží na disku, na ktorom by sťahovanie pristálo.',
  'disk.measured': 'Merané na {path}',
  'disk.elsewhereHint': 'Samotný priečinok sa zmerať nedal, meral sa preto najbližší nad ním. Ak sa nejaký mount nespustil, môže to byť úplne iný disk než ten, pre ktorý je sťahovanie určené. Pozri sa na cestu skôr, než z tých čísel niečo vyvodíš.',
  'disk.sampled': 'Odčítané pred {n} s',
  'disk.tight': 'Front sa nezmestí',
  'disk.tightHint': 'Tomuto priečinku sa dlží viac, než má disk voľného. Tento riadok sám osebe nič nezastaví: zadržiava sa po jednom, vždy keď na sťahovanie príde rad, podľa čísel na stránke nastavení Sťahovanie. Sťahovanie, ktorého veľkosť nikto nepozná, sa tu neráta vôbec.',
  'disk.truncated': 'Nie sú tu všetky priečinky',
  'disk.truncatedHint': 'Front mieri na viac priečinkov mimo tých nastavených, než sa oplatí merať pri každom odčítaní, preto tie s najmenším dlhom vypadli. Každý priečinok, ktorý si nastavil, tu je vždy.',
  'disk.markLow': 'Pod týmto sa nič nové nespustí',
  'disk.markStop': 'Pod týmto sa všetko zastaví',
  'disk.limits': 'Nastaviť hranice disku',
  'disk.stripLabel': 'Miesto v cieľových priečinkoch',
  'disk.role.downloads': 'Priečinok na sťahovanie',
  'disk.role.category': 'Priečinok kategórie',
  'disk.role.work': 'Pracovný priečinok',
  'disk.role.task': 'Nastavený priamo pri sťahovaní',

  'settings.volume.title': 'Limit objemu',
  'settings.volume.titleHint': 'Čo táto inštancia stiahla do konca, počítané proti limitu, ktorý si nastavíš, za jedno obdobie. Ráta sa veľkosť, ktorú hoster pre dokončené sťahovanie ohlásil, takže čo skončí bez uvedenej veľkosti, ráta sa ako nula, a čo torrent odošle, sa neráta vôbec. Je to vyhodnotenie tvojich sťahovaní, nie meranie tvojej linky: bajty, ktoré naozaj prehnal tvoj router, tu nikto nevidí.',
  'settings.volume.cap': 'Limit na obdobie (GB)',
  'settings.volume.capHint': '0 znamená bez limitu: počítadlo beží ďalej a nikdy sa nič nezadrží. Gigabajty sú tu desiatkové, tak ako svoj objem uvádza poskytovateľ: 500 GB je 500 000 000 000 bajtov a nie 465 GiB. Hranice disku vyššie na tejto stránke sú dvojkové GiB, iná jednotka na inú otázku.',
  'settings.volume.resetDay': 'Počítadlo sa vynuluje v deň',
  'settings.volume.resetDayHint': 'Deň v mesiaci, keď sa počítadlo vráti na nulu, zvyčajne deň, keď ti pridelia nový objem. V mesiaci kratšom než zvolený deň sa vynuluje namiesto toho v posledný deň toho mesiaca a nikdy sa neprešmykne do nasledujúceho. Ráta sa podľa hodín servera, nie podľa hodín tvojho prehliadača, lebo front zadržiava server.',
  'settings.volume.action': 'Keď sa limit dosiahne',
  'settings.volume.actionHint': 'Bežiaci prenos sa nepreruší nikdy, nech si vyberieš čokoľvek: prerušiť ho uprostred súboru znamená zahodiť bajty, ktoré si už minul. „Len mi to oznám“ nemení nič a počítadlo je potom celá tá funkcia. „Nespúšťať ďalšie sťahovania“ nechá dobehnúť to, čo beží, a zadrží front, kým sa počítadlo nespustí odznova; každý čakajúci riadok to potom aj napíše. „Všetko spomaliť“ nechá front bežať ďalej, rýchlosťou nižšie.',
  'settings.volume.actionReport': 'Len mi to oznám',
  'settings.volume.actionPause': 'Nespúšťať ďalšie sťahovania',
  'settings.volume.actionThrottle': 'Všetko spomaliť',
  'settings.volume.throttle': 'Rýchlosť po dosiahnutí limitu (KiB/s)',
  'settings.volume.throttleHint': 'Rýchlosť, ktorá platí po zvyšok obdobia. Je to strop popri tvojich ostatných limitoch a nikdy namiesto nich: nočné okno alebo tichý prepínač, ktoré žiadajú menej, vyhrávajú aj naďalej. 0 by tu znamenala vôbec žiadny limit, čiže to isté ako žiadny limit objemu, najmenšie zmysluplné číslo je teda 1.',
  'settings.volume.noCap': 'Bez limitu',
  'settings.volume.used': 'Stiahnuté v tomto období',
  'settings.volume.usedOf': '{used} z {cap}',
  'settings.volume.resetsOn': 'Vynuluje sa {date}',
  'settings.volume.reached': 'Limit je dosiahnutý.',

  'volume.title': 'Stiahnutý objem',
  'volume.titleHint': 'Dokončené sťahovania spočítané po dňoch a po mesiacoch, z histórie sťahovaní. História má vlastnú hornú hranicu a dá sa vyprázdniť ručne, mesiace, ktoré z nej vypadli, tu teda jednoducho nie sú. Sťahovanie, ktoré si spustil znova, sa ráta raz, v deň, keď sa naposledy dokončilo. Ráta sa podľa kalendára servera, v {zone}.',
  'volume.range.days': '30 dní',
  'volume.range.months': '12 mesiacov',
  'volume.split.total': 'Všetko',
  'volume.split.host': 'Podľa hostera',
  'volume.split.backend': 'Podľa backendu',
  'volume.other': 'Všetko ostatné',
  'volume.empty': 'V tomto období sa zatiaľ nič nedokončilo.',
  'volume.unsizedHint': 'Pri {n} z týchto sťahovaní hoster nikdy neuviedol veľkosť. K súčtu nepridávajú nič, skutočné číslo je teda vyššie než to nakreslené.',
  'volume.trimmedHint': 'História je na svojej vlastnej hranici, všetko staršie než jej najstarší záznam preto chýba aj v tejto krivke. Ak chceš siahať ďalej dozadu, zdvihni hornú hranicu histórie na tejto stránke.',
  'volume.meter': 'Objem',
  'volume.meterHint': 'Čo sa stiahlo do konca od posledného vynulovania počítadla, merané proti limitu na stránke nastavení Sťahovanie. Číslo sa pohne, keď je sťahovanie hotové, nie počas neho: skáče teda, namiesto toho, aby sa plazilo. Spočítava sa z histórie sťahovaní: kto históriu vyprázdni, vynuluje tým aj toto počítadlo.',

