  'health.part.captcha': 'Captchy',
  'health.remedy.store.failed': 'Databáza neodpovedala. Sťahovanie beží ďalej, ale nič sa o ňom už nezapisuje, reštart by teda stratil všetko, čo sa odvtedy zmenilo. Pozri sa, či je dátový priečinok stále pripojený a stále zapisovateľný.',
  'health.remedy.jd.unreachable': 'KL_JD uvádza adresu, ktorú táto inštancia práve nedosiahne. Pozri sa, či kontajner JDownloader beží a či jeho port API odtiaľto odpovedá. Odkazy, ktoré vie stiahnuť len JDownloader, zatiaľ zostávajú vo fronte a nezlyhali.',
  'health.remedy.jd.notWired': 'JDownloader zase odpovedá, ale tento proces si svoje backendy zapojil pri štarte a vtedy ho nemal. Reštartuj KnightLoader, aby ho prevzal.',
  'health.remedy.ytdlp.missing': 'Pri štarte tohto procesu sa nenašlo žiadne yt-dlp (KL_YTDLP alebo „yt-dlp“ v PATH). Mediálne stránky potom zlyhajú s vlastnou chybou stránky, namiesto toho, aby sa rozložili na varianty. Aby sa našlo, treba reštart.',
  'health.remedy.disk.low': 'Cieľový priečinok je pod hranicou, ktorú si nastavil na stránke Sťahovanie. Nič nové sa tam nespustí, kým nebude zase miesto alebo kým hranicu nezmenšíš. To, čo už beží, táto hranica nezastaví.',
  'health.remedy.disk.elsewhere': 'Priečinok tam nie je, hodnoty preto opisujú najbližší priečinok nad ním. Ak sa pripojenie nezdvihlo, je to úplne iný disk. Skôr než číslam uveríš, pozri sa na cestu.',
  'health.remedy.accounts.benched': 'Aspoň jeden hosterský účet sa po chybe necháva na pokoji. Až čakanie uplynie, skúsi sa sám od seba ešte raz, a čakanie sa zakaždým zdvojnásobí. Ak to chceš vedieť hneď, choď na Účty a stlač v riadku Obnoviť.',
  'health.remedy.accounts.invalid': 'Aspoň jeden hosterský účet bol odmietnutý. Pomôže nový kľúč alebo predĺžené predplatné, čakanie nie.',
  'health.remedy.feeds.failing': 'Aspoň pri jednom odbere zlyhalo posledné načítanie. Ktorý a prečo, stojí na stránke Sťahovanie vedľa kanála a v riadkoch denníka na stránke Diagnostika.',
  'health.remedy.relay.down': 'Adresa relay je uložená a spojenie nestojí. Táto inštancia to sama skúša ďalej a lokálne beží všetko ako inokedy. Nedostupná je práve len zvonka.',
  'health.remedy.captcha.waiting': 'Backend sa zastavil a pýta sa človeka. Za ním sa nepohne nič, kým niekto neodpovie.',
  'settings.health.tasks': 'Sťahovania práve teraz',
  'settings.health.tasksHint': 'Momentka zoznamu v takom stave, v akom je, nie počítadlo naprieč časom. „Zlyhané“ počíta riadky, ktoré práve stoja v zozname s chybou. Číslo teda klesá, keď ich upraceš a keď sa zoznam po nastavenom počte dní vyčistí, a znova stúpa, keď sa pokazí niečo nové. Nič tu nie je miera a nič tu nehovorí, ako často niečo zlyhalo.',
  'settings.health.running': 'Beží',
  'settings.health.waiting': 'Čaká',
  'settings.health.failed': 'Zlyhané',
  'settings.health.waitingWhy': 'Prečo čakajú',
  'settings.health.failedWhy': 'Čo sa pokazilo',
  'settings.health.nothingWaiting': 'Nič sa nezadržiava.',
  'settings.health.nothingFailed': 'V zozname nič nezlyhalo.',
  'settings.health.diskLink': 'Koľko miesta je v cieľových priečinkoch, stojí na stránke Sťahovanie',
  'settings.health.scrape': 'Monitorovanie',
  'settings.health.scrapeSwitch': 'Odpovedať na adrese s metrikami',
  'settings.health.scrapeHint': 'Otvorí druhú adresu, ktorá vydáva tie isté hodnoty ako čistý text, vo formáte, aký čítajú Prometheus a nástroje postavené podľa neho. Vyzdvihuje sa, nikdy sa neodosiela: tento stroj neopustí nič, kým sem tvoj vlastný monitoring nepríde a nespýta sa naň. Kým je toto vypnuté, adresa vôbec neexistuje a odpovedá 404, presne ako každá iná adresa, ktorú táto aplikácia nemá. Na inštancii s heslom potrebuje načítanie jeden z tvojich API tokenov, a to sa dá naučiť každý zberač. Zberač neposiela hlavičku s pôvodom a preto prejde. Karta prehliadača na inej adrese ju posiela a odmietne sa, keď nesedí s adresou tejto inštancie. V texte stoja cesty k tvojim cieľovým priečinkom. Daj ho teda len tam, kam by si dal aj samotné názvy priečinkov.',
  'settings.health.scrapeUrl': 'Adresa s metrikami',
  'settings.health.scrapeCopy': 'Kopírovať adresu',
  'settings.health.scrapeCopied': 'Adresa skopírovaná',
  'settings.health.scrapeOffHint': 'Kým je prepínač nad tým vypnutý, táto adresa neodpovedá nič.',
  'settings.diagnostics.systemTitle': 'Systémové informácie',
  'settings.diagnostics.fileTitle': 'Súbor denníka',
  'settings.diagnostics.fileOn': 'Zapisovať denník do súboru',
  'settings.diagnostics.fileOnHint': 'Vypnuté, kým to nezapneš, a aktualizácia ti to nikdy nezapne. Zapnuté zapisuje táto inštancia každý zaznamenaný riadok do súboru vo svojom dátovom priečinku, aby sa pád spred dvoch nocí dal po reštarte ešte prečítať. Riadok denníka môže uviesť adresu kanála, ktorý odoberáš, ber preto ten súbor ako svoj vlastný. V kontajneri tie isté riadky pristávajú aj v docker logs; súbor je to, čo zostane, keď to prebehne.',
  'settings.diagnostics.fileSize': 'Veľkosť na súbor',
  'settings.diagnostics.fileSizeHint': 'Len čo súbor dosiahne túto veľkosť, premenuje sa a začne nový.',
  'settings.diagnostics.fileKeep': 'Koľko starých súborov zostane',
  'settings.diagnostics.fileKeepHint': 'Koľko premenovaných súborov zostane ležať vedľa toho, do ktorého sa práve píše. Nula ponechá len aktuálny súbor. To je skutočné nastavenie a nie spôsob, ako denník vypnúť.',
  'settings.diagnostics.fileWhere': 'Kde leží',
  'settings.diagnostics.fileWhereHint': 'Pevne nastavené, aby zápis denníka nepoložil preklep v ceste. Ak ho chceš mať na inom disku, nastav pred štartom aplikácie KL_LOG_DIR.',
  'settings.diagnostics.fileStateOff': 'Nezapisuje sa',
  'settings.diagnostics.fileStateOn': 'Obsadené {size} z {max}',
  'settings.diagnostics.fileProblem': 'Súbor denníka sa nezapisuje: {error}',
  'settings.diagnostics.fileProblemHint': 'Skontroluj, či {path} existuje a či tam smie zapisovať konto, pod ktorým tento proces beží. Na Unraide priečinok väčšinou patrí rootovi, kým kontajner beží pod iným používateľom. Inak nič nezastalo: posledných {n} riadkov leží ďalej v pamäti a ďalej ide do diagnostického balíka.',
  'settings.diagnostics.fileProblemSpace': 'Na tom zväzku je voľných ešte {free}.',
  'settings.diagnostics.fileProblemSpaceUnknown': 'Koľko miesta na tom zväzku ešte zostáva, sa na tomto systéme nedá zistiť.',
  'settings.diagnostics.fileCurrent': 'Bežiaci súbor',
  'settings.diagnostics.fileOlder': 'Starší súbor {n}',
  'settings.diagnostics.fileEmpty': 'Zatiaľ nič zapísané.',
  'settings.diagnostics.fileDownload': 'Stiahnuť',
  'settings.diagnostics.logSearch': 'Prehľadať riadky',
  'settings.diagnostics.logSearchHint': 'Obyčajný text, žiadne zástupné znaky, veľké a malé písmená sa berú rovnako. Prehľadáva riadky načítané sem, nie staršie súbory. Ak chceš prehľadať celý súbor, stiahni si ho.',
  'settings.diagnostics.logSource': 'Zdroj',
  'settings.diagnostics.logSourceAll': 'Všetky zdroje',
  'settings.diagnostics.logSourceOther': 'Ostatné riadky',
  'settings.diagnostics.logSourceHint': 'Z ktorej časti aplikácie riadok pochádza, čítané zo začiatku riadka. Riadky, ktoré žiadnu časť neuvádzajú, stoja pod „Ostatné riadky“. Podľa závažnosti sa filtrovať nedá: v tejto aplikácii si ju žiadny riadok nedrží.',
  'settings.diagnostics.logFollow': 'Sledovať nové riadky',
  'settings.diagnostics.logFollowHint': 'Každé dve sekundy sa spýta, čo od posledného razu pribudlo, a skočí na najnovší riadok. Vypnuté zostane pohľad stáť, aby ti pri čítaní nič neutieklo.',
  'settings.diagnostics.logMatches': '{shown} z {total} riadkov',
  'settings.diagnostics.logNoMatches': 'Žiadny riadok tu toto neobsahuje.',
  'settings.diagnostics.logGap': 'Medzi dvoma otázkami vypadlo riadkov: {n}. Prišlo ich viac, než pojme {cap} riadkov v pamäti. Zapni súbor denníka, aby zostali zachované.',
