  'detail.log.empty': 'K tomuto sťahovaniu sa nič nezaznamenalo.',
  'detail.log.emptyHint': 'Nie každý riadok si drží, ku ktorému sťahovaniu patrí. Sťahovanie sa teda môže dostať do problémov bez toho, aby sa tu objavil jediný riadok. Celý denník stojí na stránke Diagnostika.',
  'detail.log.openDiagnostics': 'Otvoriť celý denník',
  'detail.log.remote': 'Denník zostáva na inštancii, ktorá ho zapísala. Pre sťahovanie, ktoré beží na inom stroji, tu preto nie je čo ukázať.',
  'settings.owner.identityTitle': 'Ako kto táto inštancia zapisuje',
  'settings.owner.identityHint': 'Každý súbor, ktorý táto inštancia založí, dostane tohto vlastníka a tieto práva, a rovnako tak všetko, čo spustí: yt-dlp, ffmpeg a priložený JDownloader. V kontajneri je identita daná vo chvíli, keď kontajner štartuje, určuje ju konto, pod ktorým bol spustený. Z tejto stránky sa na tom nedá nič zmeniť.',
  'settings.owner.uid': 'Používateľ',
  'settings.owner.gid': 'Skupina',
  'settings.owner.umask': 'Umask',
  'settings.owner.umaskUnknown': 'Toto jadro ju neudáva',
  'settings.owner.asked': 'Požadované',
  'settings.owner.envIgnored': '{name}={value} je nastavené, ale premennú v tomto obraze nikto nečíta. Identitu určuje konto, pod ktorým bol kontajner spustený, a to je {owner}.',
  'settings.owner.envHow': 'Ak chceš bežať pod iným kontom, uveď ho v spúšťacom príkaze: --user <uid>:<gid>. Na Unraide to patrí do Extra Parameters a kontajner sa musí vytvoriť nanovo, aby sa to prejavilo.',
  'settings.owner.desktopNote': 'Desktopová aplikácia beží pod tvojím vlastným kontom. PUID, PGID a UMASK sú nastavenia kontajnera a tu nerobia nič.',
  'settings.owner.noOwners': 'Na tomto systéme súbory vlastníkov nemajú, nie je teda čo porovnávať. To nie je chyba.',
  'settings.owner.checkTitle': 'Kontrola priečinkov',
  'settings.owner.checkHint': 'Tu sa naozaj do každého priečinka zapíše jeden súbor a jeden podpriečinok, potom sa zistí, komu oboje patrí a kto ďalší to smie čítať, a oboje sa zase odstráni. Musí sa to odmerať a nesmie sa to vypočítať: zdieľanie si môže priniesť vlastné pravidlá práv, a priečinok s nastaveným set-group-id prideľuje inú skupinu než tú, ktorú má tento proces. Kontrola beží sama od seba potom, ako uložíš zmenený priečinok, a vždy, keď stlačíš tlačidlo.',
  'settings.owner.run': 'Skontrolovať priečinky teraz',
  'settings.owner.running': 'Kontroluje sa…',
  'settings.owner.never': 'Zatiaľ neskontrolované.',
  'settings.owner.checkedAt': 'Naposledy skontrolované {time}.',
  'settings.owner.checkFailed': 'Kontrola nebežala: {error}',
  'settings.owner.role.downloads': 'Priečinok na sťahovanie',
  'settings.owner.role.work': 'Pracovný priečinok',
  'settings.owner.role.category': 'Priečinok kategórie',
  'settings.owner.role.watch': 'Sledovaný priečinok',
  'settings.owner.v.ok': 'Súbory tu pristávajú ako {fileOwner} s právami {fileMode}, nové podpriečinky s právami {subdirMode}, a samotný priečinok patrí {dirOwner}. Na tom nie je nič zvláštne.',
  'settings.owner.v.ownerMismatch': 'Súbory tu pristávajú ako {fileOwner}, priečinok však patrí {dirOwner}. Čítanie väčšinou ešte ide, premenovanie, presun a mazanie z iného konta nie, a čo očakáva, že priečinok vlastní svoj vlastný obsah, berie tieto súbory ako cudzie.',
  'settings.owner.v.groupUnreadable': 'Súbory tu pristávajú s právami {fileMode}, otvoriť ich teda dokáže len {fileOwner}. Čo beží pod iným kontom, vidí názvy a inak nič.',
  'settings.owner.v.dirUnreadable': 'Nové podpriečinky tu pristávajú s právami {subdirMode}. Dovnútra sa okrem {fileOwner} nikto nedostane, nech súbory v nich dovoľujú čokoľvek, a každé sťahovanie pristáva práve v takom priečinku.',
  'settings.owner.v.notWritable': 'Táto inštancia tu nedokáže zapisovať vôbec: {detail}',
  'settings.owner.v.missing': 'Priečinok tam nie je. Vytvorí sa, keď sa doň prvý raz bude niečo zapisovať.',
  'settings.owner.v.unknown': 'Na tomto systéme súbory vlastníkov nemajú, tu teda nie je čo porovnávať. To nie je chyba.',
  'settings.owner.fix.user': 'Spusti kontajner pod kontom, ktorému priečinok patrí: --user {dirUid}:{dirGid} v spúšťacom príkaze. Na Unraide to patrí do Extra Parameters.',
  'settings.owner.fix.chown': 'Alebo namiesto toho priečinok odovzdaj, na hostiteľovi: chown -R {uid}:{gid} {dir}',
  'settings.owner.fix.mask': 'Na tom táto inštancia nič nezmení. Maska prichádza od toho, čo kontajner spustilo, a pripojené zdieľanie môže voľbou umask, file_mode alebo dir_mode vynútiť svoju vlastnú. Naprav to tam, kde je priečinok pripojený.',
  'settings.owner.fix.recreate': 'Zmenený spúšťací príkaz potrebuje nanovo vytvorený kontajner. Reštart nestačí: identita je daná vo chvíli, keď štartuje.',
  'settings.owner.fix.past': 'Už stiahnuté súbory si podržia vlastníka, s ktorým boli zapísané. Čo zmeníš, platí pre všetko nové, na zvyšok potrebuješ príkaz vyššie.',
  'settings.selftest.title': 'Samokontrola',
  'settings.selftest.hint': 'Všetko, čo táto inštancia dokáže o sebe zistiť: sidecar JDownloader, yt-dlp, tvoje priečinky, tvoje debrid prihlásenia, relay a hodiny. Všetko to beží na tomto stroji. Jediné, čo ho opúšťa, sú debrid prihlásenia, ktoré idú k poskytovateľom, ktorých si nastavil.',
