  'settings.selftest.jd.missing': 'Žiadna adresa sidecaru. Zašifrované odkazy DLC a kontajnerové odkazy sa odmietajú.',
  'settings.selftest.jd.missingAdvice': 'Tento build pri nabiehaní normálne spúšťa svoj vlastný bezhlavý JDownloader a KL_JD si vyplní sám. To, že je prázdne, znamená: tento štart sa nepodaril. Hľadaj v denníku nižšie „JD provisioning failed“, alebo nastav KL_JD na vlastný JDownloader.',
  'settings.selftest.jd.unreachable': '{address} neodpovedala.',
  'settings.selftest.jd.unreachableAdvice': 'Adresa je uložená a nič na nej nepočúva. Skontroluj, či sidecar beží a či je jeho port 3128 dostupný z tohto kontajnera a nielen z hostiteľa.',
